1	package netdiag
2	
3	import (
4		"fmt"
5		"net"
6		"net/netip"
7		"strconv"
8		"time"
9	
10		"github.com/anthnel/devdesk/internal/netcheck"
11		"github.com/anthnel/devdesk/internal/nettrace"
12	)
13	
14	// pathStepKind says which kind of row a pathStep is.
15	type pathStepKind int
16	
17	// The kinds of row, in the order the column shows them.
18	const (
19		stepContainer pathStepKind = iota
20		stepNetwork
21		stepBridge
22		stepSource
23		stepInterface
24		stepGateway
25		stepTrace
26		stepHop
27	)
28	
29	// pathRoute is the way out of this machine for the traced address.
30	type pathRoute struct {
31		Known     bool // false: the lookup failed; interface and gateway are undetermined
32		Interface string
33		Source    netip.Addr // invalid: the stack did not say
34		Gateway   netip.Addr // invalid: directly connected
35	}
36	
37	// pathStep is one row of the Path column.
38	type pathStep struct {
39		Kind      pathStepKind
40		Container pathContainer // stepContainer, stepNetwork, stepBridge, stepTrace
41		Route     pathRoute     // stepInterface, stepGateway
42		Hop       nettrace.Hop  // stepHop
43	}
44	
45	const (
46		sourceLabel       = "this machine"
47		routeUndetermined = "undetermined"
48		gatewayDirect     = "directly connected"
49	)
50	
51	// newPathRoute converts a route lookup into a pathRoute. A failed lookup
52	// discards whatever the hop holds. Addresses are unmapped to IPv4 when they can be.
53	func newPathRoute(hop netcheck.RouteHop, err error) pathRoute {
54		if err != nil {
55			return pathRoute{}
56		}
57		return pathRoute{
58			Known:     true,
59			Interface: hop.Interface,
60			Source:    addrFromIP(hop.Source),
61			Gateway:   addrFromIP(hop.Gateway),
62		}
63	}
64	
65	// addrFromIP returns ip as an unmapped netip.Addr, or the zero Addr for a nil or invalid ip.
66	func addrFromIP(ip net.IP) netip.Addr {
67		addr, ok := netip.AddrFromSlice(ip)
68		if !ok {
69			return netip.Addr{}
70		}
71		return addr.Unmap()
72	}
73	
74	// pathSteps returns the rows of the Path column: the source, then the
75	// interface and gateway when route is not nil, then the hops as selected by
76	// visiblePathHops. It returns nil while neither a route nor a hop exists.
77	// Neither input is modified.
78	func pathSteps(ctr *pathContainer, route *pathRoute, hops []nettrace.Hop) []pathStep {
79		if ctr == nil && route == nil && len(hops) == 0 {
80			return nil
81		}
82		var steps []pathStep
83		if ctr != nil {
84			steps = append(steps,
85				pathStep{Kind: stepContainer, Container: *ctr},
86				pathStep{Kind: stepNetwork, Container: *ctr},
87			)
88			if ctr.Bridge != "" {
89				steps = append(steps, pathStep{Kind: stepBridge, Container: *ctr})
90			}
91		}
92		steps = append(steps, pathStep{Kind: stepSource})
93		if route != nil {
94			steps = append(steps,
95				pathStep{Kind: stepInterface, Route: *route},
96				pathStep{Kind: stepGateway, Route: *route},
97			)
98		}
99		if ctr != nil {
100			steps = append(steps, pathStep{Kind: stepTrace, Container: *ctr})
101		}
102		for _, h := range visiblePathHops(hops) {
103			steps = append(steps, pathStep{Kind: stepHop, Hop: h})
104		}
105		return steps
106	}
107	
108	// hopCell is the TTL of a hop row; empty for the local rows.
109	func (s pathStep) hopCell() string {
110		if s.Kind != stepHop {
111			return ""
112		}
113		return strconv.Itoa(s.Hop.TTL)
114	}
115	
116	// stepCell names the kind of row.
117	func (s pathStep) stepCell() string {
118		switch s.Kind {
119		case stepContainer:
120			return "container"
121		case stepNetwork:
122			return "network"
123		case stepBridge:
124			return "bridge"
125		case stepTrace:
126			return "trace"
127		case stepSource:
128			return "source"
129		case stepInterface:
130			return "interface"
131		case stepGateway:
132			return "gateway"
133		}
134		return s.Hop.Kind.String()
135	}
136	
137	// addressCell is the main text of the row.
138	func (s pathStep) addressCell() string {
139		switch s.Kind {
140		case stepContainer:
141			return s.Container.containerText()
142		case stepNetwork:
143			return s.Container.networkText()
144		case stepBridge:
145			return s.Container.Bridge
146		case stepTrace:
147			return s.Container.traceText()
148		case stepSource:
149			return sourceLabel
150		case stepInterface:
151			return s.Route.interfaceText()
152		case stepGateway:
153			return s.Route.gatewayText()
154		}
155		return addrOrDash(s.Hop.Addr)
156	}
157	
158	// rttCell is the round-trip time of a hop that answered; "-" otherwise.
159	func (s pathStep) rttCell() string {
160		if s.Kind != stepHop {
161			return ""
162		}
163		if s.Hop.RTT <= 0 {
164			return "-"
165		}
166		return fmt.Sprintf("%.1f ms", float64(s.Hop.RTT)/float64(time.Millisecond))
167	}
168	
169	// interfaceText is the interface name, followed by the source address when known.
170	func (r pathRoute) interfaceText() string {
171		if !r.Known || (r.Interface == "" && !r.Source.IsValid()) {
172			return routeUndetermined
173		}
174		name := r.Interface
175		if name == "" {
176			name = "unnamed"
177		}
178		if !r.Source.IsValid() {
179			return name
180		}
181		return name + " (" + r.Source.String() + ")"
182	}
183	
184	// gatewayText is the gateway address, or says the destination is directly connected.
185	func (r pathRoute) gatewayText() string {
186		switch {
187		case !r.Known:
188			return routeUndetermined
189		case !r.Gateway.IsValid() || r.Gateway.IsUnspecified():
190			return gatewayDirect
191		}
192		return r.Gateway.String()
193	}
194	
195	// addrOrDash formats an address, or "-" when there is none.
196	func addrOrDash(a netip.Addr) string {
197		if !a.IsValid() {
198			return "-"
199		}
200		return a.String()
201	}
