1	package netdiag
2	
3	import (
4		"context"
5		"fmt"
6		"log"
7		"net"
8		"net/netip"
9		"time"
10	
11		tea "charm.land/bubbletea/v2"
12	
13		"github.com/anthnel/devdesk/internal/docker"
14		"github.com/anthnel/devdesk/internal/engine"
15		"github.com/anthnel/devdesk/internal/netcheck"
16		"github.com/anthnel/devdesk/internal/netiface"
17		"github.com/anthnel/devdesk/internal/nettrace"
18	)
19	
20	// pathChanCap holds a whole trace: every hop (at most MaxHopsLimit), the
21	// resolved message and the done message. The producer therefore never waits
22	// for a reader. Contract: resolved now carries source and ctr but is still one
23	// message, so 1 resolved + MaxHopsLimit (30) hops + 1 done = 32 = pathChanCap,
24	// and sendDone never evicts resolved with the real engine.
25	const pathChanCap = nettrace.MaxHopsLimit + 2
26	
27	// pathEngine is the seam between the path tab and the network: tests replace
28	// it with a fake.
29	type pathEngine struct {
30		supported func() error
31		resolve   func(ctx context.Context, host string) ([]netip.Addr, error)
32		route     func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error)
33		trace     func(ctx context.Context, a netip.Addr, o nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error)
34	
35		engineName func() string                                                            // engine.Current().Name
36		engineOS   func(ctx context.Context) (string, error)                                // docker.EngineOperatingSystem
37		running    func(ctx context.Context) ([]docker.Container, error)                    // running containers only
38		inspect    func(ctx context.Context, id string) (docker.ContainerNetworking, error) // read-only
39		network    func(ctx context.Context, id string) (docker.NetworkBridge, error)       // docker.InspectNetworkBridge
40		interfaces func(ctx context.Context) ([]netiface.Interface, error)                  // netiface.List
41	}
42	
43	// systemPathEngine returns the engine backed by the real resolver and sockets.
44	func systemPathEngine() pathEngine {
45		env := netcheck.SystemEnv(netcheck.DefaultSettings())
46		return pathEngine{
47			supported: nettrace.Supported,
48			resolve: func(ctx context.Context, host string) ([]netip.Addr, error) {
49				return net.DefaultResolver.LookupNetIP(ctx, "ip4", host)
50			},
51			route: func(ctx context.Context, a netip.Addr) (netcheck.RouteHop, error) {
52				return env.Route(ctx, net.IP(a.AsSlice()))
53			},
54			trace:      nettrace.TraceEach,
55			engineName: func() string { return engine.Current().Name },
56			engineOS:   docker.EngineOperatingSystem,
57			running: func(ctx context.Context) ([]docker.Container, error) {
58				return docker.ListContainersContext(ctx, false)
59			},
60			inspect:    docker.InspectContainerNetworking,
61			network:    docker.InspectNetworkBridge,
62			interfaces: netiface.List,
63		}
64	}
65	
66	// pathResolvedMsg reports the address the target resolved to.
67	type pathResolvedMsg struct {
68		gen      int
69		addr     netip.Addr
70		route    netcheck.RouteHop
71		routeErr error
72		source   pathSource                 // the source at launch
73		ctr      docker.ContainerNetworking // zero for this machine
74		ctrErr   error                      // logged by the producer, never shown
75		bridge   string                     // host interface of the container's network; "" when none
76	}
77	
78	// pathSourcesMsg carries what the selector offers once the engine answered.
79	type pathSourcesMsg struct {
80		gen  int // the request it answers, so a stale answer can be dropped
81		list pathSourceList
82	}
83	
84	// loadPathSourcesCmd reads the selector's list off the Update goroutine, under
85	// its own timeout so a hung engine cannot keep the selector loading. It
86	// touches no model (Rule 110): the answer comes back as a message.
87	func loadPathSourcesCmd(gen int, timeout time.Duration, e pathEngine) tea.Cmd {
88		return func() tea.Msg {
89			return pathSourcesMsg{gen: gen, list: listPathSourcesUnder(context.Background(), timeout, e)}
90		}
91	}
92	
93	// listPathSourcesUnder reads the list under a timeout derived from parent.
94	// Only parent decides whether an error is logged: a deadline exceeded on its
95	// own is a real failure, a canceled parent is not.
96	func listPathSourcesUnder(parent context.Context, timeout time.Duration, e pathEngine) pathSourceList {
97		ctx, cancel := context.WithTimeout(parent, timeout)
98		defer cancel()
99		return readPathSources(parent, ctx, e)
100	}
101	
102	// listPathSources reads what the selector offers with a single context.
103	func listPathSources(ctx context.Context, e pathEngine) pathSourceList {
104		return readPathSources(ctx, ctx, e)
105	}
106	
107	// readPathSources reads what the selector offers. Only read-only engine calls
108	// are made (info, ps): nothing starts or enters a container. A raw error goes
109	// to the log, never to the note, unless parent was canceled.
110	func readPathSources(parent, ctx context.Context, e pathEngine) pathSourceList {
111		name := ""
112		if e.engineName != nil {
113			name = e.engineName()
114		}
115		if name != "docker" { // podman: no exec at all
116			return sourceListFrom(name, "", nil, nil, nil)
117		}
118		osName, osErr := e.engineOS(ctx)
119		if osErr != nil {
120			logSourcesError(parent, osErr)
121			return sourceListFrom(name, "", osErr, nil, nil)
122		}
123		if isDockerDesktop(osName) {
124			return sourceListFrom(name, osName, nil, nil, nil)
125		}
126		cs, psErr := e.running(ctx)
127		if psErr != nil {
128			logSourcesError(parent, psErr)
129		}
130		return sourceListFrom(name, osName, nil, cs, psErr)
131	}
132	
133	// logSourcesError logs a read failure unless the caller gave up (parent is
134	// the context received, not the one bounded by the timeout).
135	func logSourcesError(parent context.Context, err error) {
136		if parent.Err() == nil {
137			log.Printf("ERROR [netdiag/path] sources: %v", err)
138		}
139	}
140	
141	// pathHopMsg carries one hop as the engine reports it.
142	type pathHopMsg struct {
143		gen int
144		hop nettrace.Hop
145	}
146	
147	// pathDoneMsg ends a run: a result, or an error when no trace happened.
148	type pathDoneMsg struct {
149		gen    int
150		result nettrace.Result
151		err    error
152	}
153	
154	// producePath resolves the target, traces it and sends the messages to out,
155	// then closes out. It runs inside a Cmd and touches no model (Rule 110).
156	// out must have room for pathChanCap messages: sends never block, so a view
157	// that stops reading after canceling leaks nothing.
158	func producePath(ctx context.Context, gen int, tg pathTarget, src pathSource, resolveTimeout time.Duration, e pathEngine, out chan tea.Msg) {
159		defer close(out)
160		send := func(m tea.Msg) {
161			select {
162			case out <- m:
163			default:
164			}
165		}
166		// sendDone must never be lost: when the channel is full the oldest message
167		// is dropped to make room. The producer is the only sender, so one drop
168		// frees a slot for good.
169		sendDone := func(m tea.Msg) {
170			for range 2 {
171				select {
172				case out <- m:
173					return
174				default:
175				}
176				select {
177				case <-out:
178				default:
179				}
180			}
181		}
182	
183		addr, err := resolvePathTarget(ctx, tg.Host, resolveTimeout, e)
184		if err != nil {
185			if ctx.Err() == nil { // esc during the resolution is not an error
186				log.Printf("ERROR [netdiag/path] resolve %s: %v", tg.Host, err)
187			}
188			sendDone(pathDoneMsg{gen: gen, err: err})
189			return
190		}
191		// The route is asked for the address actually traced. A failure is not
192		// fatal and is never shown: the trace goes on without the route column.
193		route, routeErr := e.route(ctx, addr)
194		if routeErr != nil && ctx.Err() == nil {
195			log.Printf("ERROR [netdiag/path] route %s: %v", tg.Host, routeErr)
196		}
197		ctr, ctrErr := inspectPathSource(ctx, src, resolveTimeout, e)
198		bridge := ""
199		if ctrErr == nil && !src.isHost() {
200			bridge = readPathBridge(ctx, ctr, resolveTimeout, e)
201		}
202		send(pathResolvedMsg{gen: gen, addr: addr, route: route, routeErr: routeErr, source: src, ctr: ctr, ctrErr: ctrErr, bridge: bridge})
203	
204		res, err := e.trace(ctx, addr, nettrace.Options{}, func(h nettrace.Hop) {
205			send(pathHopMsg{gen: gen, hop: h})
206		})
207		if err != nil {
208			log.Printf("ERROR [netdiag/path] trace %s: %v", tg.Host, err)
209		}
210		sendDone(pathDoneMsg{gen: gen, result: res, err: err})
211	}
212	
213	// inspectPathSource reads the chosen container's network under its own
214	// timeout. This machine reads nothing. A failure is not fatal and is never
215	// shown: the raw error goes to the log unless the run was canceled.
216	func inspectPathSource(ctx context.Context, src pathSource, timeout time.Duration, e pathEngine) (docker.ContainerNetworking, error) {
217		if src.isHost() {
218			return docker.ContainerNetworking{}, nil
219		}
220		ictx, cancel := context.WithTimeout(ctx, timeout)
221		defer cancel()
222		ctr, err := e.inspect(ictx, src.ID)
223		if err != nil && ctx.Err() == nil {
224			log.Printf("ERROR [netdiag/path] inspect %s: %v", src.ID, err)
225		}
226		return ctr, err
227	}
228	
229	// resolvePathTarget returns the IPv4 address to trace: a literal is used as
230	// is, a name is resolved under its own timeout.
231	func resolvePathTarget(ctx context.Context, host string, timeout time.Duration, e pathEngine) (netip.Addr, error) {
232		if a, err := netip.ParseAddr(host); err == nil && a.Is4() {
233			return a, nil
234		}
235		rctx, cancel := context.WithTimeout(ctx, timeout)
236		defer cancel()
237		addrs, err := e.resolve(rctx, host)
238		if err != nil {
239			return netip.Addr{}, fmt.Errorf("%w: %w", errPathResolve, err)
240		}
241		if len(addrs) == 0 {
242			return netip.Addr{}, errPathNoIPv4
243		}
244		return addrs[0], nil
245	}
246	
247	// waitForPathMsg returns a Cmd that yields the next message of in, or nil
248	// once in is closed. The view re-arms it after every message.
249	func waitForPathMsg(in <-chan tea.Msg) tea.Cmd {
250		return func() tea.Msg {
251			m, ok := <-in
252			if !ok {
253				return nil
254			}
255			return m
256		}
257	}
