1	package netdiag
2	
3	import (
4		"errors"
5		"slices"
6		"testing"
7	
8		"github.com/charmbracelet/x/ansi"
9	
10		"github.com/anthnel/devdesk/internal/docker"
11		"github.com/anthnel/devdesk/internal/nettrace"
12	)
13	
14	// DEVDESK-331 step 3: the bridge row of the container source. Bridge is the
15	// name of the interface read on this machine; "" means there is no bridge in
16	// the path.
17	
18	// bridgeCtr returns a container built the way production builds it, in the given
19	// mode. A stopped container carries no endpoint, as the engine reports it.
20	func bridgeCtr(t *testing.T, mode string, running bool) pathContainer {
21		t.Helper()
22		n := docker.ContainerNetworking{
23			Name: "web-1", Running: running, Mode: mode,
24			Networks: []docker.EndpointNetwork{ep("app_net", "172.18.0.5", "172.18.0.1", prioOf(0))},
25		}
26		return newPathContainer(pathSource{ID: "abc123", Name: "web-1"}, n, nil)
27	}
28	
29	// A stopped container is represented by Running == false, and newPathContainer
30	// then leaves Attach at attachUndetermined, so withBridge's Attach check covers
31	// it; the "stopped" case below goes through the real constructor to prove it.
32	func TestPathContainerWithBridge(t *testing.T) {
33		failed := newPathContainer(pathSource{ID: "abc123", Name: "web-1"}, docker.ContainerNetworking{}, errors.New("boom"))
34		// two endpoints, no gateway priority: the default-route network is ambiguous
35		ambiguous := newPathContainer(pathSource{ID: "abc123", Name: "web-1"}, docker.ContainerNetworking{
36			Name: "web-1", Running: true, Mode: "app_net",
37			Networks: []docker.EndpointNetwork{
38				ep("a_net", "172.18.0.5", "172.18.0.1", nil),
39				ep("b_net", "172.19.0.5", "172.19.0.1", nil),
40			},
41		}, nil)
42	
43		tests := []struct {
44			name string
45			ctr  pathContainer
46			in   string
47			want string
48		}{
49			{"attached to a network", bridgeCtr(t, "app_net", true), "docker0", "docker0"},
50			{"user-defined bridge name", bridgeCtr(t, "app_net", true), "br-3f2a1b4c5d6e", "br-3f2a1b4c5d6e"},
51			{"empty name sets nothing", bridgeCtr(t, "app_net", true), "", ""},
52			{"host mode", bridgeCtr(t, "host", true), "docker0", ""},
53			{"none mode", bridgeCtr(t, "none", true), "docker0", ""},
54			{"shared network namespace", bridgeCtr(t, "container:abc", true), "docker0", ""},
55			{"undetermined: ambiguous default route", ambiguous, "docker0", ""},
56			{"undetermined: failed inspection", failed, "docker0", ""},
57			{"stopped container", bridgeCtr(t, "app_net", false), "docker0", ""},
58		}
59		for _, tt := range tests {
60			t.Run(tt.name, func(t *testing.T) {
61				before := tt.ctr
62				got := tt.ctr.withBridge(tt.in)
63	
64				if got.Bridge != tt.want {
65					t.Errorf("withBridge(%q).Bridge = %q, want %q", tt.in, got.Bridge, tt.want)
66				}
67				// Everything else is carried over unchanged.
68				wantRest := before
69				wantRest.Bridge = tt.want
70				if got != wantRest {
71					t.Errorf("withBridge changed more than Bridge: got %+v, want %+v", got, wantRest)
72				}
73				// The receiver is not modified.
74				if tt.ctr != before {
75					t.Errorf("withBridge modified its receiver: %+v, was %+v", tt.ctr, before)
76				}
77			})
78		}
79	}
80	
81	// Two calls from the same receiver do not leak into each other.
82	func TestPathContainerWithBridgeReturnsACopy(t *testing.T) {
83		base := bridgeCtr(t, "app_net", true)
84		a := base.withBridge("docker0")
85		b := base.withBridge("br-abc")
86		if base.Bridge != "" {
87			t.Errorf("receiver Bridge = %q, want empty", base.Bridge)
88		}
89		if a.Bridge != "docker0" || b.Bridge != "br-abc" {
90			t.Errorf("copies = %q and %q, want docker0 and br-abc", a.Bridge, b.Bridge)
91		}
92	}
93	
94	// Criterion 1: container, network, bridge, source, interface, gateway, trace, hops.
95	// Criterion 2: without a bridge, no bridge row, and the existing order holds.
96	func TestPathStepsBridgeOrder(t *testing.T) {
97		withBr := bridgeCtr(t, "app_net", true).withBridge("docker0")
98		noBr := bridgeCtr(t, "app_net", true)
99		host := bridgeCtr(t, "host", true).withBridge("docker0")
100		hops := []nettrace.Hop{stepsHop1}
101	
102		tests := []struct {
103			name  string
104			ctr   pathContainer
105			route *pathRoute
106			hops  []nettrace.Hop
107			want  []pathStepKind
108		}{
109			{"criterion 1: bridge between network and source", withBr, stepsRoute, hops,
110				[]pathStepKind{stepContainer, stepNetwork, stepBridge, stepSource, stepInterface, stepGateway, stepTrace, stepHop}},
111			{"bridge, no route, no hop", withBr, nil, nil,
112				[]pathStepKind{stepContainer, stepNetwork, stepBridge, stepSource, stepTrace}},
113			{"bridge, hop before route", withBr, nil, hops,
114				[]pathStepKind{stepContainer, stepNetwork, stepBridge, stepSource, stepTrace, stepHop}},
115			{"criterion 2: no bridge, no bridge row", noBr, stepsRoute, hops,
116				[]pathStepKind{stepContainer, stepNetwork, stepSource, stepInterface, stepGateway, stepTrace, stepHop}},
117			{"host mode never gets one", host, stepsRoute, hops,
118				[]pathStepKind{stepContainer, stepNetwork, stepSource, stepInterface, stepGateway, stepTrace, stepHop}},
119		}
120		for _, tt := range tests {
121			t.Run(tt.name, func(t *testing.T) {
122				ctr := tt.ctr
123				before := ctr
124				got := pathSteps(&ctr, tt.route, tt.hops)
125				if kinds := stepKinds(got); !slices.Equal(kinds, tt.want) {
126					t.Fatalf("kinds = %v, want %v", kinds, tt.want)
127				}
128				if ctr != before {
129					t.Errorf("pathSteps modified its container input")
130				}
131			})
132		}
133	}
134	
135	// A this-machine source with no container never shows a bridge row.
136	func TestPathStepsBridgeAbsentWithoutContainer(t *testing.T) {
