87				t.Fatalf("bridge rows = %v, want none (rows %v)", got, rowKinds(pm))
88			}
89			return
90		}
91		if !slices.Equal(got, []string{want}) {
92			t.Fatalf("bridge rows = %v, want [%s] (rows %v)", got, want, rowKinds(pm))
93		}
94	}
